# Assistant des essais sur le PC d'Alexis (tickets 15 à 20 de docs/tickets/mvp/issues).
# À lancer dans Git Bash, sous Windows :  bash scripts/essais-pc.sh
# Il ne lance aucun installeur et ne change aucun réglage Windows. Il copie config.txt
# avant le premier essai et vérifie à la fin que le fichier est revenu à l'identique.
# Les réponses sont notées dans essais-pc.env, à renvoyer à Claude.

# oui_non CLE "question" : pose une question fermée et note « oui » ou « non ».
oui_non() {
  if confirm "$2 (y = oui)"; then write_env "$1" "oui"; else write_env "$1" "non"; fi
}

# empreinte FICHIER : affiche une empreinte du contenu, ou « absent ».
empreinte() {
  if [[ -f "$1" ]]; then sha256sum "$1" | cut -d' ' -f1; else printf 'absent'; fi
}

run_wizard() {

TOTAL_STAGES=12
ENV_FILE="essais-pc.env"
DOSSIER_APO="/c/Program Files/EqualizerAPO/config"
DOSSIER_ESSAIS="$HOME/retro-eq-essais"

banner "Retro EQ : essais sur le PC"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Préparer"
say "Il te faut : le casque INZONE H9 II branché, Equalizer APO installé,"
say "et retro-eq.exe sorti du fichier retro-eq-windows-x64.zip."
note "Cet assistant ne lance aucun installeur et ne change aucun réglage Windows."
ask EXE "Chemin de retro-eq.exe (glisse le fichier dans cette fenêtre) :"
EXE="${EXE//\"/}"; EXE="${EXE//\'/}"
command -v cygpath >/dev/null 2>&1 && EXE="$(cygpath -u "$EXE")"
if [[ ! -f "$EXE" ]]; then warn "fichier introuvable : $EXE"; warn "relance l'assistant avec le bon chemin."; exit 1; fi
write_env EXE "$EXE"
if [[ -f "$DOSSIER_APO/config.txt" ]]; then
  write_env APO_INSTALLE "oui"
else
  write_env APO_INSTALLE "non"
  warn "Equalizer APO n'est pas dans « C:\\Program Files\\EqualizerAPO »."
  say "Installe-le toi-même (son installeur te fait choisir la sortie du casque,"
  say "puis demande un redémarrage), et relance cet assistant ensuite."
  open_url "https://sourceforge.net/projects/equalizerapo/"
  exit 1
fi
pause "Appuie sur Entrée pour continuer"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Mettre config.txt à l'abri"
say "Avant tout essai, on copie le config.txt d'Equalizer APO."
mkdir -p "$DOSSIER_ESSAIS"
SAUVEGARDE="$DOSSIER_ESSAIS/config.txt.avant-essais"
if [[ -f "$SAUVEGARDE" ]]; then
  note "Une copie existe déjà et n'est pas écrasée : $SAUVEGARDE"
else
  cp "$DOSSIER_APO/config.txt" "$SAUVEGARDE"
  printf '  %s✓ copié%s vers %s\n' "$GREEN" "$RESET" "$SAUVEGARDE"
fi
write_env SAUVEGARDE "$SAUVEGARDE"
write_env EMPREINTE_ORIGINE "$(empreinte "$SAUVEGARDE")"
say "On vérifie aussi que le dossier est inscriptible sans droits d'administrateur."
if : > "$DOSSIER_APO/retro-eq-essai.tmp" 2>/dev/null; then
  rm -f "$DOSSIER_APO/retro-eq-essai.tmp"; write_env DOSSIER_INSCRIPTIBLE "oui"
else
  write_env DOSSIER_INSCRIPTIBLE "non"
  warn "Le dossier config n'est pas inscriptible : Retro EQ ne pourra pas piloter le moteur."
fi
pause "Appuie sur Entrée pour continuer"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Premier lancement : rien n'est écrit sans ton accord"
AVANT="$(empreinte "$DOSSIER_APO/config.txt")"
say "Je lance Retro EQ. Windows peut afficher un écran bleu « Windows a protégé"
say "votre ordinateur » (l'appli n'est pas encore signée) :"
step "clique « Informations complémentaires », puis « Exécuter quand même »."
if command -v cygpath >/dev/null 2>&1; then explorer.exe "$(cygpath -w "$EXE")" >/dev/null 2>&1 || true
else "$EXE" >/dev/null 2>&1 & fi
step "L'écran « Premier lancement » s'affiche. NE CLIQUE PAS encore sur « Continuer »."
pause "Quand l'écran est affiché, appuie sur Entrée"
if [[ "$(empreinte "$DOSSIER_APO/config.txt")" == "$AVANT" && ! -f "$DOSSIER_APO/retro-eq.txt" ]]; then
  write_env RIEN_ECRIT_AVANT_ACCORD "oui"
else
  write_env RIEN_ECRIT_AVANT_ACCORD "non"; warn "config.txt a changé avant ton accord : c'est un défaut à corriger."
fi
oui_non AUTOTEST_CASQUE_VU "L'autotest affiche-t-il bien ton casque comme sortie ?"
oui_non AUTOTEST_MOTEUR_VU "L'autotest dit-il que le moteur audio (Equalizer APO) est détecté ?"
step "Maintenant, clique sur « Continuer » : c'est ton accord pour activer l'égaliseur."
pause "Quand c'est fait, appuie sur Entrée"
if [[ -f "$DOSSIER_APO/retro-eq.txt" ]] && grep -q "Include: retro-eq.txt" "$DOSSIER_APO/config.txt"; then
  write_env MOTEUR_BRANCHE "oui"
else
  write_env MOTEUR_BRANCHE "non"; warn "retro-eq.txt ou la ligne Include manque dans le dossier config."
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "La fenêtre"
say "La fenêtre n'a pas de bordure Windows. Elle doit avoir deux tailles seulement :"
say "1280 × 800, ou agrandie."
step "Attrape la barre du haut et déplace la fenêtre."
oui_non FENETRE_DEPLACEMENT "La fenêtre se déplace-t-elle ?"
step "Clique sur le carré (agrandir), puis encore une fois (revenir)."
oui_non FENETRE_AGRANDIR "Agrandir puis revenir à 1280 × 800 fonctionne-t-il ?"
step "Essaie d'étirer la fenêtre par un bord ou un coin."
oui_non FENETRE_ETIRABLE "Arrives-tu à l'étirer par un bord ? (attendu : non)"
step "Survole le bouton agrandir : Windows 11 propose-t-il le menu d'ancrage (Snap) ?"
oui_non FENETRE_MENU_SNAP "Le menu Snap apparaît-il ?"
step "Clique sur le trait (réduire), puis rouvre la fenêtre depuis la barre des tâches."
oui_non FENETRE_REDUIRE "Réduire puis rouvrir fonctionne-t-il ?"
step "Clique sur la croix. La fenêtre doit disparaître, l'icône rester près de l'horloge."
oui_non FERMER_GARDE_ICONE "L'icône Retro EQ est-elle près de l'horloge, et le son toujours égalisé ?"
step "Rouvre la fenêtre depuis cette icône (« Ouvrir Retro EQ »)."
pause "Quand la fenêtre est rouverte, appuie sur Entrée"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "L'égaliseur s'entend-il ?"
step "Lance une musique que tu connais bien."
step "Dans Retro EQ, onglet « Égaliseur » : monte le fader 62 à +12, puis remets-le à 0."
oui_non EQ_AUDIBLE "Entends-tu clairement les graves monter puis redescendre ?"
ask EQ_DELAI "Délai entre ton geste et le changement (immédiat / moins d'1 s / plus d'1 s) :"
write_env EQ_DELAI "$EQ_DELAI"
oui_non EQ_CLIC "Entends-tu un clic ou un craquement au moment du changement ?"
step "Bouge le fader vite, de haut en bas, pendant quelques secondes."
oui_non EQ_COUPURES "Le son se coupe-t-il ou saccade-t-il pendant que tu bouges vite ?"
step "Coupe « Égaliseur actif » : le son doit redevenir celui d'origine. Puis réactive-le."
oui_non EQ_COUPER "Couper puis réactiver l'égaliseur s'entend-il ?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Le visualiseur capte-t-il ce qui joue ?"
step "Musique toujours en lecture, ouvre l'onglet « Visualiseur »."
oui_non VISU_AIGUILLE "L'aiguille et les barres du spectre bougent-elles avec la musique ?"
step "Mets la musique en pause quelques secondes."
oui_non VISU_SILENCE "L'aiguille retombe-t-elle quand la musique s'arrête ?"
say "Question importante : la capture se fait-elle avant ou après l'égaliseur ?"
step "Relance la musique. Onglet « Égaliseur » : monte 62 à +12."
step "Reviens sur « Visualiseur » et regarde les barres de gauche (graves)."
oui_non CAPTURE_APRES_MOTEUR "Les barres des graves sont-elles nettement plus hautes qu'avant ?"
step "Remets le fader 62 à 0."
pause "Quand c'est fait, appuie sur Entrée"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Un test, les raccourcis et la bascule A/B"
step "Onglet « Tester » : garde « Duels en jeu », clique « Lancer »."
step "Choisis la bascule « 10 s », puis « Démarrer le test »."
step "Écoute un duel entier (1 minute) en laissant la fenêtre Retro EQ au premier plan."
oui_non BASCULE_AUDIBLE "Entends-tu le son changer entre A et B, au moins sur certains duels ?"
oui_non BASCULE_CLIC "Entends-tu un clic au moment des bascules ?"
oui_non BASCULE_VOLUME "A et B te semblent-elles au même volume ?"
step "Quand la question arrive, clique dans une AUTRE fenêtre (le navigateur), puis appuie sur F7."
oui_non RACCOURCI_HORS_APPLI "La réponse « Pareil » a-t-elle été prise alors que Retro EQ n'était pas au premier plan ?"
step "Au duel suivant, pendant la question : maintiens F6 une seconde, relâche, puis maintiens F8."
oui_non REECOUTE "Maintenir F6 puis F8 fait-il réentendre A puis B ?"
step "Appuie brièvement sur F6 pour répondre A, puis sur F10 pour annuler."
oui_non ANNULER "F10 a-t-il annulé ta réponse (le duel est rejoué) ?"
oui_non MINI_FENETRE "Une mini-fenêtre Retro EQ est-elle affichée en bas à droite de l'écran ?"
oui_non MINI_FOCUS "Cette mini-fenêtre te vole-t-elle le clavier quand elle apparaît ? (attendu : non)"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "En jeu"
say "Le test tourne toujours. Lance un jeu en « plein écran fenêtré » (sans bordure)."
step "Joue un duel entier, réponds avec F6, F7 ou F8 sans quitter le jeu."
oui_non JEU_FENETRE_RACCOURCIS "Les touches F6 à F8 répondent-elles pendant le jeu ?"
oui_non JEU_FENETRE_MINI "La mini-fenêtre est-elle visible par-dessus le jeu ?"
oui_non JEU_FENETRE_GENE "Le jeu a-t-il perdu le focus ou ralenti à cause de la mini-fenêtre ?"
step "Reviens sur Retro EQ, onglet « Tester » : le journal doit nommer l'appli détectée."
oui_non JEU_APPLI_DETECTEE "Retro EQ a-t-il reconnu le jeu comme appli au premier plan ?"
say "Si ton jeu propose un « plein écran exclusif », passe dessus pour un duel."
if confirm "As-tu un jeu avec plein écran exclusif à essayer ? (y = oui)"; then
  oui_non JEU_EXCLUSIF_RACCOURCIS "En plein écran exclusif, F6 à F8 répondent-elles ?"
  oui_non JEU_EXCLUSIF_BIP "Un bip court confirme-t-il chaque réponse ?"
else
  write_env JEU_EXCLUSIF_RACCOURCIS "non essayé"
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Appel Discord"
say "Le test doit se mettre en pause tout seul pendant un appel."
step "Test en cours, Discord ouvert mais SANS appel : attends 30 secondes."
oui_non DISCORD_FAUSSE_PAUSE "Le test s'est-il mis en pause alors que tu n'étais pas en appel ? (attendu : non)"
step "Rejoins un salon vocal ou lance un appel."
oui_non DISCORD_PAUSE "Le test s'est-il mis en pause dans les secondes qui suivent ?"
step "Quitte l'appel."
oui_non DISCORD_REPRISE "Le test a-t-il repris tout seul ?"
ask DISCORD_MODE_MICRO "Ton micro Discord est en (détection de la voix / appuyer pour parler) :"
write_env DISCORD_MODE_MICRO "$DISCORD_MODE_MICRO"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Arrêt brutal en plein duel"
say "On vérifie qu'une variante ne reste pas active après un plantage."
step "Laisse un duel en cours d'écoute (pas en pause, pas pendant la question)."
if confirm "Puis-je tuer Retro EQ maintenant, comme un plantage ? (y = oui)"; then
  taskkill //IM retro-eq.exe //F >/dev/null 2>&1 || warn "impossible de tuer retro-eq.exe : ferme-le depuis le Gestionnaire des tâches."
  say "Retro EQ est arrêté. Le son est peut-être encore sur une variante : c'est attendu."
  step "Relance retro-eq.exe toi-même."
  pause "Quand il est relancé, appuie sur Entrée"
  oui_non REPRISE_PROPOSEE "Retro EQ propose-t-il de reprendre le test interrompu, en pause ?"
  oui_non REPRISE_REPONSES "Les réponses déjà données sont-elles toujours là (numéro du duel conservé) ?"
  step "Reprends le test, puis clique « Arrêter le test… »."
  write_env ARRET_BRUTAL "essayé"
else
  write_env ARRET_BRUTAL "non essayé"
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Export vers Peace"
say "Le format .peace a été reconstitué d'après des fichiers réels, jamais ouvert dans Peace."
step "Onglet « Mes profils » : choisis ton profil, clique l'export « Peace »."
step "Retro EQ annonce le chemin du fichier (dans Documents › Retro EQ)."
if confirm "Peace est-il installé sur ce PC pour ouvrir ce fichier ? (y = oui)"; then
  step "Dans Peace : « Import », choisis le fichier .peace exporté."
  oui_non PEACE_OUVRE "Peace ouvre-t-il le fichier sans erreur, avec les bonnes bandes ?"
else
  write_env PEACE_OUVRE "non essayé"
fi
step "Toujours dans « Mes profils » : « Importer un fichier… », choisis un de tes vrais presets Peace."
oui_non IMPORT_PEACE "L'import de ton preset Peace donne-t-il une courbe qui lui ressemble ?"
ask IMPORT_MESSAGE "Recopie le message affiché après l'import (lignes ignorées, s'il y en a) :"
write_env IMPORT_MESSAGE "$IMPORT_MESSAGE"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Rendre le son d'origine"
say "Dernier essai : Retro EQ doit rendre config.txt exactement comme il l'a trouvé."
step "Onglet « Réglages », tout en bas : « Rendre le son d'origine »."
pause "Quand c'est fait, appuie sur Entrée"
if [[ "$(empreinte "$DOSSIER_APO/config.txt")" == "$EMPREINTE_ORIGINE" ]]; then
  write_env CONFIG_RENDU_A_L_IDENTIQUE "oui"
  printf '  %s✓ config.txt est identique à la copie du début%s\n' "$GREEN" "$RESET"
else
  write_env CONFIG_RENDU_A_L_IDENTIQUE "non"
  warn "config.txt diffère de la copie du début."
  if confirm "Remettre maintenant la copie du début à la place ? (y = oui)"; then
    cp "$SAUVEGARDE" "$DOSSIER_APO/config.txt" && printf '  %s✓ copie du début remise%s\n' "$GREEN" "$RESET"
  fi
fi
if [[ -f "$DOSSIER_APO/retro-eq.txt" ]]; then write_env RETRO_EQ_TXT_RETIRE "non"; else write_env RETRO_EQ_TXT_RETIRE "oui"; fi
oui_non SON_ORIGINE "Le son est-il redevenu celui d'avant Retro EQ ?"
ask REMARQUES "Une remarque libre sur ces essais (ou Entrée pour passer) :" || true
write_env REMARQUES "${REMARQUES:-}"

finish
say "Les réponses sont dans : $(pwd)/$ENV_FILE"
say "Envoie le contenu de ce fichier à Claude : il s'en sert pour corriger."
printf '\n'
}

run_wizard "$@"; exit
